import json,numpy as np
from scipy.spatial.transform import Rotation
from rcb_client import Robot
from PIL import Image
S=json.load(open('/app/output/spec.json'))
RANGES=np.array(S['qpos']['range']); AX=np.array(S['proprio']['axis']); JP=np.array(S['proprio']['position_m'])
NAMES=S['links']['names']; PARENTS=S['links']['parent']; COM=np.array(S['links']['com_m']); MASS=np.array(S['links']['mass_kg'])
JN=S['qpos']['layout']; LINKJOINT={n+'_link':i for i,n in enumerate(JN)}
def rot(axis,q): return Rotation.from_rotvec(np.array(axis)*q).as_matrix()
def transforms(q):
    ts={'pelvis':(np.eye(3),np.zeros(3))}
    for name,parent in zip(NAMES[1:],PARENTS[1:]):
        R,t=ts[parent]
        if name in LINKJOINT:
            i=LINKJOINT[name]; A=rot(AX[i],q[i]); ts[name]=(R@A,t+R@(JP[i]-A@JP[i]))
        else: ts[name]=(R,t)
    return ts
def point(q,name,p):
    R,t=transforms(q)[name]; return R@p+t
def hand(q): return point(q,'left_hand',COM[NAMES.index('left_hand')])
def com(q):
    ts=transforms(q); return sum(m*(ts[n][0]@p+ts[n][1]) for n,p,m in zip(NAMES,COM,MASS))/MASS.sum()
def action(q): return np.clip(2*(np.asarray(q)-RANGES[:,0])/(RANGES[:,1]-RANGES[:,0])-1,-1,1)
def save(o,tag='view'):
    for k,v in o.get('images',{}).items(): Image.fromarray(v).save('/app/output/'+tag+'_'+k+'.png')
    with open('/app/output/obs.json','w') as f: json.dump({k:v for k,v in o.items() if k not in ['images','depth']},f)
def summary(o): return {k:v for k,v in o.items() if k not in ['images','depth']}
BASE=np.zeros(19); BASE[[2,7]]=-.4; BASE[[3,8]]=.8; BASE[[4,9]]=-.4
if __name__=='__main__':
    import sys
    r=Robot(); task=json.loads(sys.argv[1]); o=r.observe(False)
    if task.get('reset'): o=r.reset(False)
    q=np.array(task.get('q',BASE.tolist())); steps=task.get('steps',0)
    if steps: o=r.step('qpos',[action(q).tolist()]*steps,images=True)
    else: o=r.observe(True)
    save(o); print(json.dumps(summary(o)))
