from control import *
def statics(q):
 ts=transforms(q); ps={n:ts[n][0]@p+ts[n][1] for n,p in zip(NAMES,COM)}
 co=sum(ps[n]*m for n,m in zip(NAMES,MASS))/sum(MASS); torque=np.zeros(19)
 def desc(n,a):
  while n is not None:
   if n==a:return True
   n=PARENTS[NAMES.index(n)]
  return False
 for n,i in LINKJOINT.items():
  R,t=ts[PARENTS[NAMES.index(n)]]; j=R@JP[i]+t; ax=R@AX[i]; mom=np.zeros(3)
  for cn,m in zip(NAMES,MASS):
   if desc(cn,n):mom+=np.cross(ps[cn]-j,[0,0,-m*9.81])
  if i<10:
   # each supporting leg bears half load, lateral pressure about mid-foot
   sg=1 if i<5 else -1
   cop=np.array([co[0],sg*.203, -1.065])
   mom+=np.cross(cop-j,[0,0,MASS.sum()*9.81/2])
  torque[i]=-mom@ax
 return torque
if __name__=='__main__':
 for q in [BASE,np.zeros(19)]: print(statics(q))
